import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [symbol, setSymbol] = useState('BBCA.JK');
  const [stockData, setStockData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [exchangeRate, setExchangeRate] = useState(15500); // Default IDR/USD rate

    const fetchStock = async () => {
        setLoading(true);
      setError(null);
        try {
            const res = await axios.get("http://localhost:5000/stock", {
                params: { symbol }
            });

        if (res.data && Array.isArray(res.data.data)) {
          // Convert USD values to IDR
          const convertedData = res.data.data.map(item => ({
            ...item,
            Open: item.Open * exchangeRate,
            High: item.High * exchangeRate,
            Low: item.Low * exchangeRate,
            Close: item.Close * exchangeRate
          }));
          setStockData(convertedData);
            } else {
          setError('Invalid data format received from server');
          setStockData([]);
            }
        } catch (err) {
            console.error('Error details:', err);
        setStockData([]);

            if (err.response) {
                if (err.response.status === 404) {
            setError(`No data found for symbol: ${symbol}`);
                } else {
            setError(`Server error: ${err.response.data?.error || 'Unknown error'}`);
                }
            } else if (err.request) {
          setError('Server not responding. Please check if backend is running.');
            } else {
          setError(`Failed to fetch data: ${err.message}`);
            }
        } finally {
            setLoading(false);
        }
    };

useEffect(() => {
  fetchStock();
  // eslint-disable-next-line react-hooks/exhaustive-deps
}, [symbol, exchangeRate]);
// Currency conversion handler
const handleExchangeRateChange = (e) => {
  const rate = parseFloat(e.target.value);
  if (!isNaN(rate) && rate > 0) {
    setExchangeRate(rate);
  }
};


return (
    <div style={{ padding: '2rem' }}>
    <h1>Stock Data Viewer (IDR)</h1>
    <div style={{ margin: '1rem 0', display: 'flex', gap: '10px', alignItems: 'center' }}>
      <input
          type="text"
          value={symbol}
          onChange={(e) => setSymbol(e.target.value)}
        placeholder="Enter stock symbol (e.g., BBCA.JK)"
        style={{ padding: '8px' }}
      />
      <button
        onClick={fetchStock}
        style={{ padding: '8px 16px', cursor: 'pointer' }}
        disabled={loading}
      >
        {loading ? 'Loading...' : 'Fetch Data'}
      </button>
    </div>
    <div style={{ marginTop: '10px' }}>
      <label htmlFor="exchangeRate">IDR/USD Exchange Rate: </label>
      <input
        id="exchangeRate"
        type="number"
        value={exchangeRate}
        onChange={handleExchangeRateChange}
        style={{ padding: '6px', width: '100px' }}
      />
      <button
        onClick={() => fetchStock()}
        style={{ padding: '6px 12px', marginLeft: '10px' }}
      >
        Update
      </button>
    </div>

    {error && <div style={{ color: 'red', margin: '1rem 0' }}>{error}</div>}

      {loading ? (
      <p>Loading data...</p>
    ) : stockData.length > 0 ? (
      <table border="1" cellPadding="5" style={{ marginTop: '1rem', borderCollapse: 'collapse' }}>
        <thead style={{ backgroundColor: '#f2f2f2' }}>
            <tr>
            <th>Date</th>
              <th>Open</th>
              <th>High</th>
              <th>Low</th>
              <th>Close</th>
              <th>Volume</th>
            </tr>
            </thead>
            <tbody>
            {stockData.map((row, i) => (
                <tr key={i}>
              <td>{row.Date || row.Datetime}</td>
              <td>Rp {typeof row.High === 'number' ? row.High.toLocaleString('id-ID') : '-'}</td>
              <td>Rp {typeof row.Low === 'number' ? row.Low.toLocaleString('id-ID') : '-'}</td>
              <td>Rp {typeof row.Close === 'number' ? row.Close.toLocaleString('id-ID') : '-'}</td>
              <td>{typeof row.Volume === 'number' ? row.Volume.toLocaleString('id-ID') : '-'}</td>
                </tr>
            ))}
            </tbody>
          </table>
    ) : !error && (
      <p>No data available. Please enter a valid stock symbol and fetch data.</p>
      )}
    </div>
);
}

export default App;
